        rows_A.append(non_zero)

    # Read dimensions of matrix B
    p, q = map(int, input().split())
    if m != p:
        print("Incompatible dimensions")
        return

    mat_B = []
    for _ in range(p):
        row = list(map(int, input().split()))
        mat_B.append(row)

    # Prepare rows_B: list of lists of (column, value) pairs for non-zero elements in each row of B
    rows_B = []
    for row in mat_B:
        non_zero = []
        for col in range(q):
            val = row[col]
            if val != 0:
                non_zero.append((col, val))
        rows_B.append(non_zero)

    # Initialize result matrix with zeros
    result = [[0] * q for _ in range(n)]

    # Compute the product
