        m = L[-1][0]
        if m == n:
            for i in range(len(L)-1, -1, -1):
                if L[i][1] == '+':
                    L = L[:i] + [[L[i][0], '-']]
                    break
        else:
            L += [[v, '+'] for v in range(m+1, n)] + [[n, '-']]
        a.append(''.join(f"{x}{s}" for x,s in L))
print('\n'.join(a))
