import sys
from collections import defaultdict

def main():
    N = int(sys.stdin.readline())
    inverted_index = defaultdict(set)

    for doc_id in range(N):
        document = sys.stdin.readline().strip().lower()
        words = document.split()
        for word in words:
            inverted_index[word].add(doc_id)

    Q = int(sys.stdin.readline())
    for _ in range(Q):
        query = sys.stdin.readline().strip().lower()
        terms = query.split()
        if not terms:
            print("No match")
        else:
            # Collect all sets for each term in the query
            sets_list = []
            for term in terms:
                sets_list.append(inverted_index[term])
            # Compute intersection of all sets
            common = sets_list[0]
            for s in sets_list[1:]:
                common = common.intersection(s)
                if not common:
                    break  # Early exit if empty
            # Check the result
            if not common:
                print("No match")
            else:
                for doc_id in sorted(common):
                    print(doc_id)
        print()  # Print blank line after each query's results

if __name__ == "__main__":
    main()
