import ast

def multiply_nested(elem, factor):
    if isinstance(elem, int):
        return elem * factor
    elif isinstance(elem, list):
        return [multiply_nested(e, factor) for e in elem]
    else:
        raise ValueError("Invalid element type found")

def main():
    try:
        # Read and parse the list
        list_input = input().strip()
        the_list = ast.literal_eval(list_input)
        if not isinstance(the_list, list):
            raise ValueError("Input is not a list")

        # Read and parse the factor
        factor_input = input().strip()
        factor = int(factor_input)

        # Process the list
        result = multiply_nested(the_list, factor)
        print(result)

    except Exception:
        print("Error")

if __name__ == "__main__":
    main()
