                const Point &A = red[i], &B = red[j], &C = red[k];

                // Precompute edge vectors for triangle A, B, C
                int dx_ab = B.x - A.x;
                int dy_ab = B.y - A.y;
                int dx_bc = C.x - B.x;
                int dy_bc = C.y - B.y;
                int dx_ca = A.x - C.x;
                int dy_ca = A.y - C.y;

                for (const auto &Q : blue) {
                    // Compute (dx_ab)*(Q.y - A.y) - (dy_ab)*(Q.x - A.x)
                    int dx_qa = Q.x - A.x;
                    int dy_qa = Q.y - A.y;
                    int c1 = dx_ab * dy_qa - dy_ab * dx_qa;

                    // Compute (dx_bc)*(Q.y - B.y) - (dy_bc)*(Q.x - B.x)
                    int dx_qb = Q.x - B.x;
                    int dy_qb = Q.y - B.y;
                    int c2 = dx_bc * dy_qb - dy_bc * dx_qb;

                    // Compute (dx_ca)*(Q.y - C.y) - (dy_ca)*(Q.x - C.x)
                    int dx_qc = Q.x - C.x;
                    int dy_qc = Q.y - C.y;
                    int c3 = dx_ca * dy_qc - dy_ca * dx_qc;

                    // Check if any cross is zero (point on edge)
                    if (c1 == 0 || c2 == 0 || c3 == 0) {
