using namespace std;

typedef long long ll;
const int N = 1e5 + 5;

int a[N];
ll invA[N], invB[N];

struct Fenwick {
    vector<ll> bit;
    Fenwick(int n) : bit(n + 1, 0) {}
    void add(int i, int val) {
        for (; i < bit.size(); i += i & -i)
            bit[i] += val;
    }
    ll query(int i) {
        ll res = 0;
        for (; i > 0; i -= i & -i)
            res += bit[i];
        return res;
    }
};

int main() {
