    sort(temp.begin(), temp.end());
    temp.erase(unique(temp.begin(), temp.end()), temp.end());

    auto get_rank = [&](int x) {
        return lower_bound(temp.begin(), temp.end(), x) - temp.begin() + 1;
    };

    // Compute invA using Fenwick Tree
    Fenwick bit1(temp.size() + 2);
    invA[0] = 0;
    for (int i = 1; i <= n; i++) {
        int rank = get_rank(a[i]);
        int cnt_less = bit1.query(rank - 1);
        invA[i] = invA[i - 1] + (i - 1 - cnt_less);
        bit1.add(rank, 1);
