import sys

def main():
    roman = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    s = input().strip()

    if len(s) == 0:
        print("Error: Input must be a non-empty string")
        sys.exit()

    for char in s:
        if char not in roman:
            print(f"Error: '{char}' is not a valid Roman numeral character")
            sys.exit()

    total = 0
    n = len(s)
    for i in range(n - 1):
        current = roman[s[i]]
        next_val = roman[s[i+1]]
        if current < next_val:
            total -= current
        else:
            total += current
    total += roman[s[-1]]
    print(total)

if __name__ == "__main__":
    main()
