public class MaximizeCountSerializer {
    public static void main(String[] args) throws Exception {
        ByteArrayOutputStream bos = new ByteArrayOutputStream();
        ObjectOutputStream oos = new ObjectOutputStream(bos);
        // Create an array with 499 Code instances (root object)
        Code[] codes = new Code[499];
        for (int i = 0; i < 499; i++) {
            codes[i] = new Code();
        }
        oos.writeObject(codes); // root object is the array (~500 total objects)
        oos.close();
        System.out.write(bos.toByteArray());
