    runD = [[0]*m for _ in range(n)]
    for j in range(m):
        for i in range(n-1, -1, -1):
            if grid[i][j] == 'R':
                if i == n-1:
                    runD[i][j] = 1
                else:
                    runD[i][j] = 1 + runD[i+1][j]
            else:
                runD[i][j] = 0

    # Initialize DP table
    dp = [[0]*m for _ in range(n)]
    dp[0][0] = 1  # Starting cell

    for i in range(n):
        for j in range(m):
            if i == 0 and j == 0:
                continue
            total = 0
            # Check from above (i-1, j)
            if i > 0:
                if grid[i][j] == '.':
                    up_allow = True
                else:
                    if runD[i][j] <= ( (n-1 - i) ):
                        up_allow = True
                    else:
                        up_allow = False
                if up_allow:
                    total += dp[i-1][j]
            # Check from the left (i, j-1)
            if j > 0:
                if grid[i][j] == '.':
                    left_allow = True
                else:
                    if runR[i][j] <= ( (m-1 - j) ):
                        left_allow = True
                    else:
                        left_allow = False
                if left_allow:
                    total += dp[i][j-1]
            dp[i][j] = total % MOD

    print(dp[n-1][m-1] % MOD)

