    # Case 2: check for m=2, solving n^2 - n = x -1
    discriminant = 1 + 4 * (x - 1)
    sqrt_d = int(math.isqrt(discriminant))
    if sqrt_d * sqrt_d == discriminant and (1 + sqrt_d) % 2 == 0:
        n = (1 + sqrt_d) // 2
        if n >= 2:
            return (n, 2)

    return (-1, -1)

def main():
    import sys
    input = sys.stdin.read().split()
    t = int(input[0])
    test_cases = list(map(int, input[1:t+1]))
    for x in test_cases:
        n, m = solve_case(x)
        if n == -1:
            print(-1)
        else:
            print(n, m)

if __name__ == "__main__":
    main()
```

