def fibonacci(n):
    def fast_doubling(n):
        if n == 0:
            return (0, 1)
        a, b = fast_doubling(n // 2)
        c = a * (2 * b - a)
        d = a * a + b * b
        return (d, c + d) if n % 2 else (c, d)

    if n == 0:
        return 0
    else:
        return fast_doubling(n)[0]

